// crush-replay-001-whole-command: The write guard allows whole command
func TestCrushReplay001WholeCommand(t *testing.T) {
	s := scenarios.New(t, "crush-replay-001-whole-command")
	s.Given(`the "crush-replay-whole-command" project tree`)
	s.And(`crush's write policy grants the test command "go test ./..." with selector "-run" in "."`)
	s.And(`crush pipes a shell call in directory "." with command go test ./...`)
	s.When(`crush asks the guard about the tool call`)
	s.Then(`the guard allows the tool call`)
	s.Done()
}

