// crush-replay-014-writer-background-result: The build code crush writer runs its declared replay selection through bash and reads a test lasting over a minute through job_output
func TestCrushReplay014WriterBackgroundResult(t *testing.T) {
	s := scenarios.New(t, "crush-replay-014-writer-background-result")
	s.Given(`the "build-code-writer-replay" project tree`)
	s.And(`the System Architect answers "1" to every question`)
	s.When(`the System Architect runs "build code --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches BUILD CODE COMPLETE`)
	s.And(`every file matching "tmp/*/crush-config-*/crush.json" matches "bash"`)
	s.And(`every file matching "tmp/*/crush-config-*/crush.json" matches "job_output"`)
	s.And(`every file matching "tmp/*/crush-config-*/crush.json" matches "job_kill"`)
	s.And(`the file "services/calc/guard-calls.jsonl" matches "tool": "bash"`)
	s.And(`the file "services/calc/guard-calls.jsonl" matches "tool": "job_output"`)
	s.And(`the file "services/calc/guard-calls.jsonl" matches "elapsed_seconds": ([6-9][0-9]|[1-9][0-9]{2,})`)
	s.And(`every file matching "tmp/*/crush-turn*-crush.log" matches job_output`)
	s.And(`every file matching "tmp/*/crush-turn*-crush.log" matches SELECTION COMPLETED`)
	s.And(`the file "services/calc/replayed.txt" matches ^SELECTION COMPLETED`)
	s.And(`the file "tests/suite/replay_test.go" is unchanged`)
	s.And(`the engine dispatched 1 apply AI turn to "crush"`)
	s.Done()
}

// crush-replay-015-unrepresentable-command: A replay argument containing a single quote withholds the writer grant with one warning
func TestCrushReplay015UnrepresentableCommand(t *testing.T) {
	s := scenarios.New(t, "crush-replay-015-unrepresentable-command")
	s.Given(`the "build-code-unrepresentable-replay" project tree`)
	s.And(`the System Architect answers "1" to every question`)
	s.When(`the System Architect runs "build code --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches level=WARN msg="Replay command grant unavailable"`)
	s.And(`stdout matches argument contains a single quote, newline or NUL`)
	s.And(`the file matching "tmp/true-bdd.log.json" has exactly 1 match for Replay command grant unavailable`)
	s.And(`every file matching "tmp/*/crush-config-*/crush.json" does not match "bash"`)
	s.And(`every file matching "tmp/*/crush-config-*/crush.json" does not match "job_output"`)
	s.Done()
}
